approval_reason:
function aggregateReason(perCommand) {
	if (perCommand.length === 1) {
		return perCommand[0]?.reason ?? "policy result";
	};
	const allowed = [];
	const asked = [];
	const denied = [];
	perCommand.forEach((ev, idx) => {
		const label = `[${idx}] ${ev.matchedRuleSource ?? ev.source}`;
		if (ev.kind === "allow") {
			allowed.push(label);
		} else if (ev.kind === "ask") {
			asked.push(label);
		} else {
			denied.push(label);
		}
	});
	const parts = [];
	if (allowed.length > 0) {
		parts.push(`auto-allow: ${allowed.join(", ")}`);
	};
	if (asked.length > 0) {
		parts.push(`needs-approval: ${asked.join(", ")}`);
	};
	if (denied.length > 0) {
		parts.push(`denied: ${denied.join(", ")}`);
	};
	return parts.join("; ");
} (model requested approval)

